<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import type { UserCreateInput, UserStatus, UserSummary } from '@cyberboard/types'
import StatusBadge from '@cyberboard/ui/components/StatusBadge.vue'
import StatePanel from '@cyberboard/ui/components/StatePanel.vue'
import { adminApi, getApiErrorMessage, normalizePage } from '../api'

const query = ref(''); const statusFilter = ref('all'); const page = ref(1); const pageSize = 20; const total = ref(0); const loading = ref(true); const saving = ref(false); const error = ref(''); const formError = ref(''); const showForm = ref(false); const editingId = ref<string | null>(null); const users = ref<UserSummary[]>([])
const form = reactive<UserCreateInput>({ email:'', displayName:'', password:'', status:'active' })
const filtered = computed(() => users.value)
const formatTraffic = (used:number, quota:number) => `${(used/1e9).toFixed(0)} / ${(quota/1e9).toFixed(0)} GB`
function resetForm() { Object.assign(form,{email:'',displayName:'',password:'',status:'active',planId:undefined}); editingId.value=null; showForm.value=false; formError.value='' }
function edit(user: UserSummary) { Object.assign(form,{email:user.email,displayName:user.displayName,password:'',status:user.status}); editingId.value=user.id; showForm.value=true; formError.value='' }
async function load() { loading.value=true; error.value=''; try { const result=normalizePage(await adminApi.listUsers({page:page.value,pageSize,search:query.value,status:statusFilter.value==='all'?undefined:statusFilter.value}),page.value,pageSize); users.value=result.items; total.value=result.total } catch(cause) { users.value=[]; total.value=0; error.value=getApiErrorMessage(cause) } finally { loading.value=false } }
async function save() { saving.value=true; formError.value=''; try { if(editingId.value) await adminApi.updateUser(editingId.value,{email:form.email,displayName:form.displayName,password:form.password||undefined,status:form.status}); else await adminApi.createUser(form); resetForm(); await load() } catch(cause) { formError.value=getApiErrorMessage(cause) } finally { saving.value=false } }
async function toggleStatus(user:UserSummary) { try { await adminApi.updateUser(user.id,{status:user.status==='active'?'suspended':'active'}); await load() } catch(cause) { error.value=getApiErrorMessage(cause) } }
function search() { page.value=1; load() }
onMounted(load)
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">账户与权限</p><h1>用户</h1><p>服务端分页管理账户、套餐和流量额度。</p></div><button class="primary-button" type="button" @click="showForm=true;editingId=null">+ 创建用户</button></div>
  <section v-if="showForm" class="panel form-panel"><div class="panel-heading"><div><h2>{{ editingId ? '编辑用户' : '创建用户' }}</h2><p>保存后由控制面校验字段和权限。</p></div><button class="button button--secondary" type="button" @click="resetForm">取消</button></div><form class="resource-form" @submit.prevent="save"><label>邮箱<input v-model="form.email" type="email" required :disabled="saving" /></label><label>显示名称<input v-model="form.displayName" required :disabled="saving" /></label><label>密码<input v-model="form.password" type="password" :required="!editingId" :placeholder="editingId?'留空表示不修改':''" :disabled="saving" /></label><label>状态<select v-model="form.status" :disabled="saving"><option value="active">正常</option><option value="suspended">暂停</option><option value="banned">封禁</option></select></label><p v-if="formError" class="form-error" role="alert">{{ formError }}</p><button class="primary-button" type="submit" :disabled="saving">{{ saving?'保存中…':'保存用户' }}</button></form></section>
  <section class="panel"><div class="toolbar"><input v-model="query" class="search-input" placeholder="搜索邮箱或用户名" @keyup.enter="search" /><select v-model="statusFilter" aria-label="用户状态" @change="search"><option value="all">全部状态</option><option value="active">正常</option><option value="suspended">暂停</option><option value="banned">封禁</option></select><button class="button button--secondary" type="button" :disabled="loading" @click="search">{{ loading?'加载中…':'查询' }}</button></div><StatePanel v-if="loading" title="正在加载用户" description="正在读取账户状态和套餐额度。" /><StatePanel v-else-if="error" title="用户加载失败" :description="error" action-label="重试" @action="load" /><StatePanel v-else-if="!filtered.length" title="暂无用户" description="当前筛选条件没有服务端数据。" action-label="清除筛选" @action="query='';statusFilter='all';search()" /><div v-else class="table-wrap"><table><thead><tr><th>用户</th><th>状态</th><th>套餐</th><th>流量</th><th>到期时间</th><th>最近活动</th><th>操作</th></tr></thead><tbody><tr v-for="user in filtered" :key="user.id"><td><strong>{{ user.displayName }}</strong><small>{{ user.email }}</small></td><td><StatusBadge :status="user.status" /></td><td>{{ user.plan }}</td><td class="mono">{{ formatTraffic(user.usedBytes,user.quotaBytes) }}</td><td>{{ user.expiresAt }}</td><td>{{ user.lastSeenAt ? new Date(user.lastSeenAt).toLocaleString() : '—' }}</td><td><button class="row-action" type="button" @click="edit(user)">编辑</button><button class="row-action" type="button" @click="toggleStatus(user)">{{ user.status==='active'?'暂停':'启用' }}</button></td></tr></tbody></table><div class="pagination"><button class="button button--secondary" :disabled="page<=1||loading" @click="page--;load()">上一页</button><span>第 {{ page }} 页 · 共 {{ total }} 条</span><button class="button button--secondary" :disabled="page*pageSize>=total||loading" @click="page++;load()">下一页</button></div></div></section>
</template>
